// ==== Instellingen ====
const LISTEN_HOST = '0.0.0.0';
const LISTEN_PORT = 1502;
const TARGET_HOST = '172.19.211.243';
const TARGET_PORT = 502;

//const CLOSE_TARGET_AFTER_REQUEST = false; // true = korte verbinding per Modbus-call, false = blijvende verbinding
const CLOSE_TARGET_AFTER_REQUEST = true; // true = korte verbinding per Modbus-call, false = blijvende verbinding
const REQUEST_TIMEOUT_MS = 3000;          // alleen relevant bij CLOSE_TARGET_AFTER_REQUEST=true

const RETRY_DELAY_MS = 5000;              // wachttijd voor herstart-poging bij server-fout
const WATCHDOG_INTERVAL_MS = 30000;       // periodieke health-check

// ==== Helpers ====
function hex(buf) {
    return buf.toString('hex').match(/.{1,2}/g).join(' ');
}

function parseMbap(buf) {
    if (buf.length < 8) return { error: 'buffer te kort voor MBAP header (' + buf.length + ' bytes)' };
    return {
        transactionId: buf.readUInt16BE(0),
        protocolId: buf.readUInt16BE(2),
        length: buf.readUInt16BE(4),
        unitId: buf.readUInt8(6),
        functionCode: buf.readUInt8(7),
        exception: (buf.readUInt8(7) & 0x80) !== 0
    };
}

// Verwachte totale framelengte o.b.v. MBAP length-veld (6 header-bytes + length-waarde)
function expectedFrameLength(buf) {
    if (buf.length < 6) return null;
    return 6 + buf.readUInt16BE(4);
}

function closeSocket(sock) {
    if (!sock) return;
    try {
        if (typeof sock.destroy === 'function') sock.destroy();
        else if (typeof sock.end === 'function') sock.end();
    } catch (e) {
        node.warn('Kon socket niet sluiten: ' + e.message);
    }
}

function sendStatus(level, message, extra) {
    // level: 'info' | 'warn' | 'error'
    const statusMsg = { topic: 'repeater-status', payload: Object.assign({ level: level, message: message, time: new Date().toISOString() }, extra || {}) };
    node.send([null, statusMsg]); // output 2
    if (level === 'error') { node.error(message); node.status({ fill: 'red', shape: 'ring', text: message }); }
    else if (level === 'warn') { node.warn(message); node.status({ fill: 'yellow', shape: 'ring', text: message }); }
    else { node.warn(message); node.status({ fill: 'green', shape: 'dot', text: message }); }
}

// ==== Server-opbouw ====
function startServer() {
    let server;
    try {
        server = net.createServer((clientSocket) => {
            const clientAddr = clientSocket.remoteAddress + ':' + clientSocket.remotePort;
            sendStatus('info', 'Management verbonden: ' + clientAddr);

            if (!CLOSE_TARGET_AFTER_REQUEST) {
                // ---- Persistente modus: één blijvende targetSocket voor de hele clientsessie ----
                const targetSocket = new net.Socket();

                targetSocket.on('error', (e) => {
                    sendStatus('error', 'Target error: ' + e.message, { clientAddr: clientAddr, target: TARGET_HOST + ':' + TARGET_PORT });
                    closeSocket(clientSocket);
                });

                targetSocket.connect(TARGET_PORT, TARGET_HOST, () => {
                    sendStatus('info', 'Verbonden met slave ' + TARGET_HOST + ':' + TARGET_PORT);
                });

                clientSocket.on('data', (data) => {
                    try {
                        const mbap = parseMbap(data);
                        node.send([{ topic: 'mgmt->slave', payload: data, raw: hex(data), mbap: mbap }, null]);
                        if (!targetSocket.destroyed) targetSocket.write(data);
                    } catch (e) {
                        sendStatus('error', 'Fout bij verwerken mgmt->slave: ' + e.message);
                    }
                });

                targetSocket.on('data', (data) => {
                    try {
                        const mbap = parseMbap(data);
                        node.send([{ topic: 'slave->mgmt', payload: data, raw: hex(data), mbap: mbap }, null]);
                        if (!clientSocket.destroyed) clientSocket.write(data);
                    } catch (e) {
                        sendStatus('error', 'Fout bij verwerken slave->mgmt: ' + e.message);
                    }
                });

                clientSocket.on('close', () => { sendStatus('info', 'Management gesloten: ' + clientAddr); closeSocket(targetSocket); });
                targetSocket.on('close', () => closeSocket(clientSocket));
                clientSocket.on('error', (e) => { sendStatus('error', 'Client error: ' + e.message, { clientAddr: clientAddr }); closeSocket(targetSocket); });

            } else {
                // ---- Per-request modus: nieuwe, korte targetSocket per Modbus-call ----
                let requestQueue = Promise.resolve(); // voorkomt overlappende requests door elkaar

                clientSocket.on('data', (requestData) => {
                    const mbapReq = parseMbap(requestData);
                    node.send([{ topic: 'mgmt->slave', payload: requestData, raw: hex(requestData), mbap: mbapReq }, null]);

                    requestQueue = requestQueue.then(() => new Promise((resolve) => {
                        const targetSocket = new net.Socket();
                        let responseBuf = Buffer.alloc(0);
                        let settled = false;

                        const finish = () => {
                            if (settled) return;
                            settled = true;
                            clearTimeout(timeoutHandle);
                            closeSocket(targetSocket);
                            resolve();
                        };

                        const timeoutHandle = setTimeout(() => {
                            sendStatus('warn', 'Timeout op antwoord van slave (per-request modus)', { clientAddr: clientAddr });
                            finish();
                        }, REQUEST_TIMEOUT_MS);

                        targetSocket.on('error', (e) => {
                            sendStatus('error', 'Target error (per-request): ' + e.message, { clientAddr: clientAddr, target: TARGET_HOST + ':' + TARGET_PORT });
                            finish();
                        });

                        targetSocket.connect(TARGET_PORT, TARGET_HOST, () => {
                            targetSocket.write(requestData);
                        });

                        targetSocket.on('data', (chunk) => {
                            responseBuf = Buffer.concat([responseBuf, chunk]);
                            const expected = expectedFrameLength(responseBuf);
                            if (expected !== null && responseBuf.length >= expected) {
                                const mbapResp = parseMbap(responseBuf);
                                node.send([{ topic: 'slave->mgmt', payload: responseBuf, raw: hex(responseBuf), mbap: mbapResp }, null]);
                                if (!clientSocket.destroyed) clientSocket.write(responseBuf);
                                finish();
                            }
                        });
                    }));
                });

                clientSocket.on('close', () => sendStatus('info', 'Management gesloten: ' + clientAddr));
                clientSocket.on('error', (e) => sendStatus('error', 'Client error: ' + e.message, { clientAddr: clientAddr }));
            }
        });

        server.on('error', (e) => {
            sendStatus('error', 'Server error: ' + e.message + ' — herstart over ' + (RETRY_DELAY_MS / 1000) + 's');
            try { server.close(); } catch (err) { /* al dicht, negeer */ }
            const t = setTimeout(startServer, RETRY_DELAY_MS);
            context.set('restartTimer', t);
        });

        server.listen(LISTEN_PORT, LISTEN_HOST, () => {
            sendStatus('info', 'Repeater luistert op ' + LISTEN_HOST + ':' + LISTEN_PORT + ' (modus: ' + (CLOSE_TARGET_AFTER_REQUEST ? 'per-request' : 'persistent') + ')');
        });

        context.set('server', server);
    } catch (e) {
        sendStatus('error', 'Kon server niet starten: ' + e.message + ' — herstart over ' + (RETRY_DELAY_MS / 1000) + 's');
        const t = setTimeout(startServer, RETRY_DELAY_MS);
        context.set('restartTimer', t);
    }
}

startServer();

// ==== Watchdog: periodieke health-check of de server daadwerkelijk nog luistert ====
const watchdog = setInterval(() => {
    const server = context.get('server');
    if (!server || !server.listening) {
        sendStatus('warn', 'Watchdog: server luistert niet meer, herstart wordt gestart');
        startServer();
    }
}, WATCHDOG_INTERVAL_MS);
context.set('watchdog', watchdog);

finalize:
const server = context.get('server');
const watchdog = context.get('watchdog');
const restartTimer = context.get('restartTimer');

if (watchdog) clearInterval(watchdog);
if (restartTimer) clearTimeout(restartTimer);
if (server) server.close();

